# Construct projective plane of order 3
# Points: 1-dimensional subspaces of GF(3)^3
# Lines: 2-dimensional subspaces (i.e., orthogonal complements)

# We'll enumerate points as non-zero vectors (x,y,z) up to scalar multiplication
# Use canonical representation: first non-zero coordinate is 1

import itertools

def canonical(v):
    # v is tuple of ints mod 3
    # find first non-zero
    for i, val in enumerate(v):
        if val != 0:
            # scale so that this val is 1
            inv = {1:1, 2:2}[val]  # 2*2=4≡1 mod3, so inv of 2 is 2
            factor = inv
            return tuple((val * factor) % 3 for val in v)
    return v  # zero vector (shouldn't happen)

points = []
for x in range(3):
    for y in range(3):
        for z in range(3):
            if x==0 and y==0 and z==0:
                continue
            v = canonical((x,y,z))
            if v not in points:
                points.append(v)

print("Points:", points)
print("Number of points:", len(points))

# Lines: each line corresponds to a non-zero normal vector (a,b,c) up to scalar
# The line is the set of points (x,y,z) such that a*x + b*y + c*z = 0 mod 3
lines = []
for a in range(3):
    for b in range(3):
        for c in range(3):
            if a==0 and b==0 and c==0:
                continue
            # get canonical normal
            nm = canonical((a,b,c))
            # compute line points
            line_pts = []
            for p in points:
                if (a*p[0] + b*p[1] + c*p[2]) % 3 == 0:
                    line_pts.append(p)
            # sort for canonical representation
            line_pts.sort()
            # store as tuple of point indices
            line_indices = tuple(sorted([points.index(p) for p in line_pts]))
            if line_indices not in [l for l in lines]:
                lines.append(line_indices)

print("Number of lines:", len(lines))
print("Lines:", lines)

# Check each line has 4 points
for idx, line in enumerate(lines):
    print(f"Line {idx}: {line} (size {len(line)})")

# Create incidence matrix 13x13
inc = [[0]*13 for _ in range(13)]
for pi in range(13):
    for li, line in enumerate(lines):
        if pi in line:
            inc[pi][li] = 1

# Check row sums
for i, row in enumerate(inc):
    print(f"Row {i} sum: {sum(row)}")
# Check column sums
for j in range(13):
    col_sum = sum(inc[i][j] for i in range(13))
    print(f"Col {j} sum: {col_sum}")
# Check pairwise inner products
for i1 in range(13):
    for i2 in range(i1+1, 13):
        dot = sum(inc[i1][j]*inc[i2][j] for j in range(13))
        if dot != 1:
            print(f"Pair ({i1},{i2}) inner product = {dot}")

